<?php require __DIR__.'/config/bootstrap.php';$q=db()->prepare("SELECT * FROM pages WHERE slug=? AND status='published'");$q->execute([slugify($_GET['slug']??'')]);$p=$q->fetch();if(!$p){http_response_code(404);exit('Page not found');}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title><?=e($p['meta_title']?:$p['title'])?></title><meta name="description" content="<?=e($p['meta_description'])?>"><link rel="stylesheet" href="/assets/css/store.css"></head><body><main class="panel"><a href="/">Home</a><h1><?=e($p['title'])?></h1><article><?=nl2br(e($p['body']))?></article></main></body></html>